package com.campuslink.controller;
import com.campuslink.common.ApiResponse; import com.campuslink.config.AuthContext; import com.campuslink.domain.Notification; import com.campuslink.dto.Requests; import com.campuslink.service.AccountService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class AccountController { private final AccountService service; @GetMapping("/users/me") public ApiResponse<Map<String,Object>> me(){return ApiResponse.ok(service.profile(AuthContext.userId()));} @PutMapping("/users/me") public ApiResponse<Map<String,Object>> update(@Valid @RequestBody Requests.Profile dto){return ApiResponse.ok(service.update(AuthContext.userId(),dto));} @GetMapping("/wallet") public ApiResponse<Map<String,Object>> wallet(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){return ApiResponse.ok(service.wallet(AuthContext.userId(),page,size));} @GetMapping("/notifications") public ApiResponse<Map<String,Object>> notifications(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){return ApiResponse.ok(service.notifications(AuthContext.userId(),page,size));} @PostMapping("/notifications/{id}/read") public ApiResponse<Void> read(@PathVariable Long id){service.readNotification(AuthContext.userId(),id);return ApiResponse.ok();} }
